```js
// One-off (#2105): moves stylesheets' colours onto palette.css. Not committed.
import { readFileSync, writeFileSync } from "node:fs";
const [paletteFile, indexFile, ...files] = process.argv.slice(2);
const lin = (c) => ((c /= 255) <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
function oklab([r, g, b]) {
  [r, g, b] = [lin(r), lin(g), lin(b)];
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s];
}
function rgba(text) {
  if (text === "white") return [255, 255, 255, 1];
  if (text === "black") return [0, 0, 0, 1];
  if (text.startsWith("#")) {
    let h = text.slice(1);
    if (h.length <= 4) h = [...h].map((c) => c + c).join("");
    const n = [0, 2, 4, 6].map((i) => parseInt(h.slice(i, i + 2), 16));
    return [n[0], n[1], n[2], h.length === 8 ? n[3] / 255 : 1];
  }
  const v = text.slice(text.indexOf("(") + 1, -1).replace(/[,/]/g, " ").trim().split(/\s+/);
  if (!text.startsWith("rgb") || v.slice(0, 3).some((s) => s.endsWith("%"))) throw new Error(`no rule for ${text}`);
  const a = v[3] === undefined ? 1 : v[3].endsWith("%") ? parseFloat(v[3]) / 100 : parseFloat(v[3]);
  return [Number(v[0]), Number(v[1]), Number(v[2]), a];
}
const PALETTE = [...readFileSync(paletteFile, "utf8").matchAll(/(--pal-[a-z0-9-]+):\s*(#[0-9a-f]{6});/g)].map(([, name, hex]) => ({ name, lab: oklab(rgba(hex)) }));
const TOKENS = new Set([...readFileSync(indexFile, "utf8").match(/:root\s*\{([^}]*)\}/)[1].matchAll(/(--[a-z0-9-]+)\s*:/g)].map((m) => m[1]));
function onPalette(text) {
  const [r, g, b, a] = rgba(text);
  if (a <= 0) return "transparent";
  const lab = oklab([r, g, b]);
  const d = (p) => Math.hypot(lab[0] - p.lab[0], lab[1] - p.lab[1], lab[2] - p.lab[2]);
  const best = PALETTE.reduce((x, y) => (d(y) < d(x) ? y : x));
  return a >= 1 ? `var(${best.name})` : `color-mix(in srgb, var(${best.name}) ${Math.round(a * 1000) / 10}%, transparent)`;
}
const COLOUR = /#[0-9a-fA-F]{3,8}\b|rgba?\([^()]*\)|hsla?\([^()]*\)|(?<![\w.#-])(?:white|black)(?![\w-])/g;
const FALLBACK = /var\((--[a-z0-9-]+)\s*,\s*(#[0-9a-fA-F]{3,8}|rgba?\([^()]*\))\s*\)/g;
for (const file of files) {
  const parts = readFileSync(file, "utf8").split(/(\/\*[\s\S]*?\*\/|url\([^)]*\))/);
  const out = parts.map((part, i) => (i % 2 === 1 ? part : part
    .replace(FALLBACK, (all, name) => (TOKENS.has(name) ? `var(${name})` : all))
    .replace(COLOUR, (lit) => (lit.startsWith("#") && ![4, 5, 7, 9].includes(lit.length) ? lit : onPalette(lit)))));
  writeFileSync(file, out.join(""));
}
```

